import {ActionMenu, ActionList} from '@primer/react'
import {useState} from 'react'
import {useLocation} from '@github-ui/react-router'
import {clsx} from 'clsx'
import styles from './CopilotOrganizationGeneralAccessDropdown.module.css'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useNavigate} from '@github-ui/use-navigate'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {CopilotOrganizationGeneralAccessOptions} from '../../utils/copilot-plan-options'

export interface CopilotOrganizationGeneralAccessDropdownProps {
  enablementSetting: string
  isTrial: boolean
}

export function CopilotOrganizationGeneralAccessDropdown({
  enablementSetting,
  isTrial,
}: CopilotOrganizationGeneralAccessDropdownProps) {
  const {basePath} = useNavigation()
  const navigate = useNavigate()
  const location = useLocation()
  const [selectedOption, setSelectedOption] = useState<{text: string; value: string}>(() => {
    const initialOption = CopilotOrganizationGeneralAccessOptions.find(option => option.value === enablementSetting)
    return initialOption || {text: 'Disabled', value: 'organizations_disabled'}
  })
  const [isLoading, setLoading] = useState(false)

  const handleOptionChange = async (option: {text: string; value: string}) => {
    const formData = new FormData()
    formData.append('copilot_enabled', option.value)
    try {
      setLoading(true)
      const response = await verifiedFetch(`${basePath}/settings/update_copilot_enablement`, {
        method: 'PUT',
        body: formData,
      })
      if (!response.ok) {
        throw new Error(`${response.status} on ${response.url}`)
      }
      setSelectedOption(option)
      // Obtain the tab query parameter and add it to the path
      const params = new URLSearchParams(location.search)
      const tab = params.get('tab')
      let path = `${basePath}/licensing/copilot`
      if (tab) {
        path += `?tab=${encodeURIComponent(tab)}`
      }
      navigate(path)
    } catch {
      setLoading(false)
      throw new Error('Failed to update organization access settings')
    }
  }

  return (
    <div className={'mb-4'} data-testid="licensing-copilot-access-org-enablement">
      <div className="pb-2">
        <h2>Copilot access</h2>
      </div>
      <div className={clsx('Box', styles.box, 'p-3', styles.border, styles.positionRelative, 'color-shadow-small')}>
        <div>
          <h3 className="mt-1">Organization access</h3>
          <p className={clsx('color-fg-muted mt-2', styles.textWrap)}>
            Control which organizations can assign Copilot licenses. Organization owners will receive an email with
            instructions.
          </p>
        </div>
        <div className={styles.topRightButton}>
          <ActionMenu>
            <ActionMenu.Button loading={isLoading} aria-disabled={isLoading} inactive={isTrial}>
              {selectedOption.text}
            </ActionMenu.Button>
            <ActionMenu.Overlay style={{maxWidth: '320px'}}>
              <ActionList selectionVariant="single">
                {CopilotOrganizationGeneralAccessOptions.map(option => (
                  <ActionList.Item
                    inactiveText={
                      isTrial
                        ? option.value !== 'all_organizations'
                          ? 'Unavailable during a trial'
                          : 'All organizations have access to Copilot during a trial'
                        : ''
                    }
                    key={option.value}
                    onSelect={() => handleOptionChange(option)}
                    selected={selectedOption.value === option.value}
                    data-testid={`org-item-${option.value.replace('_', '-').toLowerCase()}`}
                  >
                    <span
                      className={clsx(
                        option.value === 'organizations_disabled' && !isTrial
                          ? 'color-fg-danger'
                          : 'font-weight-normal',
                      )}
                    >
                      {option.text}
                    </span>
                    <p className={'color-fg-muted mt-1'}>{option.subtext}</p>
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>
      </div>
    </div>
  )
}

try{ CopilotOrganizationGeneralAccessDropdown.displayName ||= 'CopilotOrganizationGeneralAccessDropdown' } catch {}