import {useCallback, useState, useEffect, useRef} from 'react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useDebounce} from '@github-ui/use-debounce'
import type {User, Organization, BusinessTeam} from '../types'

type SearchType = 'users' | 'organizations' | 'enterprise_teams' | 'all_members'
const endpointMap: Record<SearchType, string> = {
  users: 'user_licenses',
  organizations: 'organization_licenses',
  enterprise_teams: 'enterprise_team_licenses',
  all_members: 'all_member_licenses',
}

type SearchResult<T extends SearchType> = T extends 'users'
  ? User[]
  : T extends 'organizations'
    ? Organization[]
    : T extends 'enterprise_teams'
      ? BusinessTeam[]
      : never[]

const DEBOUNCE_MS = 400

interface UseEnterpriseCopilotAccessFetchOptions {
  basePath: string
  searchQuery: string
  searchType: SearchType
  withAccess?: boolean
  page?: number
}

export function useEnterpriseCopilotAccessFetch<T extends SearchType>({
  basePath,
  searchQuery,
  searchType,
  withAccess = false,
  page,
}: UseEnterpriseCopilotAccessFetchOptions): {
  results: SearchResult<T>
  loading: boolean
  isEmpty: boolean
  fetchCompleted: boolean // Indicates if a successful fetch has been completed
  totalCount: number
} {
  const [results, setResults] = useState<SearchResult<T>>([] as SearchResult<T>)
  const [loading, setLoading] = useState<boolean>(false)
  const [isEmpty, setIsEmpty] = useState<boolean>(true)
  const [fetchCompleted, setFetchCompleted] = useState<boolean>(false)
  const [totalCount, setTotalCount] = useState<number>(0)
  const abortRef = useRef<AbortController | null>(null)

  const fetchNow = useCallback(
    async (query: string): Promise<void> => {
      const skipQuery = (!query || query.length < 1) && !withAccess
      if (skipQuery) {
        setResults([] as SearchResult<T>)
        setIsEmpty(true)
        setLoading(false)
        setFetchCompleted(true)
        setTotalCount(0)
        return
      }

      // Cancel previous request
      if (abortRef.current) {
        abortRef.current.abort()
      }
      const controller = new AbortController()
      abortRef.current = controller

      setLoading(true)
      setIsEmpty(false)

      try {
        const endpoint = endpointMap[searchType]
        const params = new URLSearchParams()
        if (query) params.append('query', query)
        if (withAccess !== undefined) params.append('withAccess', String(withAccess))
        if (page !== undefined) params.append('page', String(page))
        const queryString = params.toString() ? `?${params.toString()}` : ''
        const response = await verifiedFetch(`${basePath}/licensing/${endpoint}${queryString}`, {
          method: 'GET',
          headers: {Accept: 'application/json'},
          signal: controller.signal,
        })

        if (response.ok) {
          const data = (await response.json()) || {}
          let searchResults: SearchResult<T> = [] as SearchResult<T>
          searchResults = withAccess ? data.withCopilotAccess || [] : data.withoutCopilotAccess || []
          setResults(searchResults)
          setIsEmpty((searchResults || []).length === 0)
          setFetchCompleted(true)
          setTotalCount(data.totalCount || 0)
        } else {
          setResults([] as SearchResult<T>)
          setIsEmpty(true)
          setTotalCount(0)
        }
      } catch (err: unknown) {
        if (err instanceof Error && err.name !== 'AbortError') {
          setResults([] as SearchResult<T>)
          setIsEmpty(true)
          setTotalCount(0)
        }
      } finally {
        setLoading(false)
      }
    },
    [basePath, searchType, withAccess, page],
  )

  const debouncedFetch = useDebounce(fetchNow, DEBOUNCE_MS)

  const search = useCallback(
    (query: string) => {
      debouncedFetch(query)
    },
    [debouncedFetch],
  )

  useEffect(() => {
    search(searchQuery)
  }, [searchQuery, search, page])

  useEffect(() => {
    return () => {
      if (abortRef.current) {
        abortRef.current.abort()
        abortRef.current = null
      }
    }
  }, [])

  return {results, loading, isEmpty, fetchCompleted, totalCount}
}
