import {Banner, Button, CounterLabel, Dialog, Stack} from '@primer/react'
import {ListItem} from '@github-ui/list-view/ListItem'
import {GitHubAvatar} from '@github-ui/github-avatar'
import styles from './CopilotUserGrantAccessDialog.module.css'
import {ListView} from '@github-ui/list-view'
import {useState} from 'react'
import {SearchBar} from '@github-ui/licensing-common/components/SearchBar'
import {CopilotUserChangeAccessDialog} from './CopilotUserChangeAccessDialog'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import type {User} from '../../types'
import {XIcon} from '@primer/octicons-react'

export interface CopilotUserGrantAccessDialogProps {
  onDialogClose: () => void
  atMaxCopilotLicenseCount?: boolean
  isCopilotAllMembersFlagEnabled?: boolean
}

export function CopilotUserGrantAccessDialog(props: CopilotUserGrantAccessDialogProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedUsers, setSelectedUsers] = useState<User[]>([])
  const [showConfirmationDialog, setShowConfirmationDialog] = useState(false)
  const {basePath} = useNavigation()

  const {
    results: users,
    loading,
    isEmpty,
  } = useEnterpriseCopilotAccessFetch({
    basePath,
    searchQuery,
    searchType: 'users',
    withAccess: false,
  })

  const handleUserSelect = (user: User) => {
    // Check if user is already selected
    if (!selectedUsers.some(selectedUser => selectedUser.id === user.id)) {
      setSelectedUsers([...selectedUsers, user])
    }
  }

  const handleUserRemove = (userId: number) => {
    setSelectedUsers(selectedUsers.filter(user => user.id !== userId))
  }

  const handleAddLicenses = () => {
    if (selectedUsers.length > 0) {
      setShowConfirmationDialog(true)
    }
  }

  const handleActivateEnterprise = () => {
    window.location.href = `${basePath}/settings/billing/upgrade`
  }

  const handleCloseConfirmationDialog = () => {
    setShowConfirmationDialog(false)
  }

  return (
    <>
      <Dialog
        title="Assign licenses"
        subtitle="Search for and select members to give Copilot Business access to. Users that already have access from an organization or team will only be charged for one license."
        onClose={props.onDialogClose}
        footerButtons={[
          {
            content: 'Cancel',
            buttonType: 'default',
            onClick: props.onDialogClose,
          },
          {
            content: props.atMaxCopilotLicenseCount ? 'Activate Enterprise' : 'Add licenses',
            buttonType: 'primary',
            onClick: props.atMaxCopilotLicenseCount ? handleActivateEnterprise : handleAddLicenses,
            disabled: !props.atMaxCopilotLicenseCount && selectedUsers.length === 0,
          },
        ]}
      >
        {props.atMaxCopilotLicenseCount && (
          <Banner
            variant="warning"
            className="mb-3"
            data-testid="copilot-trial-limit-banner"
            title="License Limit Reached"
          >
            Trial accounts are limited to 50 Copilot seats. Upgrade to a paid enterprise to continue to assign more
            licenses.
          </Banner>
        )}
        {!props.atMaxCopilotLicenseCount && (
          <>
            <div className="flex-1" data-testid="licensing-copilot-user-grant-search">
              <SearchBar
                searchQuery={searchQuery}
                setSearchQuery={setSearchQuery}
                placeholder={'Search for members'}
                ariaLabel={'Search for members'}
                autoFocus
              />
            </div>
            {searchQuery && (
              <ListView
                title={'Members'}
                className={`border border-muted rounded-2 mb-3 ${styles.scrollableListView}`}
                data-testid="licensing-copilot-user-grant-access-list"
              >
                {loading ? (
                  <ListItem title={<span />}>
                    <div className={`text-center p-3 ${styles.stretchedText}`}>Loading members...</div>
                  </ListItem>
                ) : isEmpty || users.length === 0 ? (
                  <ListItem title={<span />}>
                    <div className={`text-center p-3 ${styles.stretchedText}`}>
                      No members found matching your search.
                    </div>
                  </ListItem>
                ) : (
                  (users as User[]).map(user => (
                    <ListItem
                      key={user.id}
                      data-testid={`user-li-${user.login}`}
                      className={styles.clickableListItem}
                      title={
                        <Button
                          variant="invisible"
                          block
                          alignContent="start"
                          size="large"
                          className={styles.userSelectButton}
                          leadingVisual={() => <GitHubAvatar src={user.avatarUrl} size={16} />}
                          onClick={() => handleUserSelect(user)}
                        >
                          {user.login}
                          <span className={`text-small color-fg-muted ${styles.userName}`}>{user.name}</span>
                        </Button>
                      }
                    />
                  ))
                )}
              </ListView>
            )}
          </>
        )}

        {selectedUsers.length > 0 && (
          <div className="mb-1">
            <h3 className="mb-2 text-small text-bold">
              Selected members <CounterLabel>{selectedUsers.length}</CounterLabel>
            </h3>
            <div className={styles.selectedUsersContainer}>
              {selectedUsers.map(user => (
                <Stack
                  key={`selected-${user.id}`}
                  data-testid={`selected-user-item-${user.login}`}
                  className={styles.selectedUserItem}
                  direction="horizontal"
                  gap="condensed"
                  align="center"
                >
                  <GitHubAvatar src={user.avatarUrl} size={16} />
                  <Stack direction="horizontal" gap="none" align="center">
                    <span className="text-small text-bold">{user.login}</span>
                    <Button
                      variant="invisible"
                      size="small"
                      data-testid={`remove-user-${user.id}`}
                      className={styles.removeButton}
                      aria-label={`Remove ${user.login}`}
                      onClick={() => handleUserRemove(user.id)}
                    >
                      <XIcon size={12} className="color-fg-muted" />
                    </Button>
                  </Stack>
                </Stack>
              ))}
            </div>
          </div>
        )}
      </Dialog>
      {showConfirmationDialog && (
        <CopilotUserChangeAccessDialog
          users={selectedUsers.map(user => user.id)}
          downgrade={false}
          onClose={handleCloseConfirmationDialog}
          isCopilotAllMembersFlagEnabled={props.isCopilotAllMembersFlagEnabled}
        />
      )}
    </>
  )
}

try{ CopilotUserGrantAccessDialog.displayName ||= 'CopilotUserGrantAccessDialog' } catch {}