import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemDescriptionItem} from '@github-ui/list-view/ListItemDescriptionItem'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import type {BusinessTeam} from '../../types'
import styles from './CopilotBusinessTeamAccessList.module.css'
import pluralize from 'pluralize'
import {ActionList, Button, Label, Pagination, Spinner} from '@primer/react'
import {useCheckboxSelection} from '@github-ui/licensing-common/hooks/useCheckboxSelection'
import {CopilotBusinessTeamChangeAccessDialog} from './CopilotBusinessTeamChangeAccessDialog'
import {useState} from 'react'
import {usePagination} from '../../hooks/use-pagination'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {Blankslate} from '@primer/react/experimental'

export interface CopilotBusinessTeamAccessListProps {
  setOpenGrantAccessDialog: (arg0: boolean) => void
  isCopilotBusinessTeamFlagEnabled: boolean
  pageSize?: number
  searchQuery?: string
  isTrial?: boolean
}

export function CopilotBusinessTeamAccessList(props: CopilotBusinessTeamAccessListProps) {
  const {basePath} = useNavigation()
  const [selectedTeamForDialog, setSelectedTeamForDialog] = useState<number | number[] | null>(null)

  // Fetch teams with Copilot access
  const {
    results: teams,
    loading,
    isEmpty,
    fetchCompleted,
  } = useEnterpriseCopilotAccessFetch<'enterprise_teams'>({
    basePath,
    searchQuery: props.searchQuery || '',
    searchType: 'enterprise_teams',
    withAccess: true,
  })

  const handleOpenLicenseRemovalDialog = (teamId: number) => {
    setSelectedTeamForDialog(teamId)
  }

  const handleCloseLicenseRemovalDialog = () => {
    setSelectedTeamForDialog(null)
  }

  /** Set up pagination */
  const {
    currentPage,
    totalPages,
    paginatedItems: paginatedTeams,
    navigateToPage,
  } = usePagination(teams, {pageSize: props.pageSize || 20})

  /** Checkbox management for bulk team selection - only for current page */
  const {
    selectedItems: selectedTeams,
    handleSelectItem: handleSelectUser,
    handleSelectAll,
  } = useCheckboxSelection(paginatedTeams, (team: BusinessTeam) => team.id)

  let mainContent
  let pagination
  let showBorder = true

  if (loading) {
    mainContent = (
      <Blankslate>
        <Blankslate.Description>
          <Spinner size="medium" />
        </Blankslate.Description>
      </Blankslate>
    )
  } else {
    if (fetchCompleted) {
      if (isEmpty) {
        // If we've had a successful fetch, and no enterprise teams have Copilot, show empty state instead of ListView.
        mainContent = (
          <Blankslate>
            <Blankslate.Heading>No enterprise teams with licenses</Blankslate.Heading>
            <Blankslate.Description>
              Enterprise teams who have been granted Copilot Business licenses will be visible here
            </Blankslate.Description>
          </Blankslate>
        )
      } else {
        showBorder = false
        mainContent = (
          <ListView
            title="Enterprise teams"
            isSelectable
            singularUnits="team"
            pluralUnits="teams"
            totalCount={teams.length}
            selectedCount={selectedTeams.size}
            metadata={
              <ListViewMetadata
                title={
                  selectedTeams.size > 0
                    ? `${selectedTeams.size} enterprise ${pluralize('team', selectedTeams.size)} selected`
                    : `${pluralize('enterprise team', teams.length, true)}`
                }
                onToggleSelectAll={handleSelectAll}
                actionsLabel="Actions"
                actions={
                  selectedTeams.size > 0
                    ? [
                        {
                          key: 'remove-bulk-access',
                          render(isOverflowMenu) {
                            const handleBulkRemoveAccess = () => {
                              setSelectedTeamForDialog(Array.from(selectedTeams))
                            }

                            return isOverflowMenu ? (
                              <ActionList.Item id="button:remove-bulk-access" onSelect={handleBulkRemoveAccess}>
                                Remove access
                              </ActionList.Item>
                            ) : (
                              <Button
                                id="button:remove-bulk-access"
                                variant="danger"
                                className={styles.bulkDisableButton}
                                onClick={handleBulkRemoveAccess}
                              >
                                Remove access
                              </Button>
                            )
                          },
                        },
                      ]
                    : []
                }
              />
            }
            className="border border-muted rounded-2"
            data-testid="licensing-copilot-enterprise-team-access-list-view"
          >
            {paginatedTeams.map((team: BusinessTeam) => (
              <ListItem
                key={team.id}
                isSelected={selectedTeams.has(team.id)}
                onSelect={() => handleSelectUser(team.id)}
                title={
                  <ListItemTitle
                    value={team.name}
                    href={team.teamUrl}
                    trailingBadges={
                      team.expirationDate
                        ? [
                            <Label key="expiration" variant="attention" size="small">
                              Expires on {team.expirationDate}
                            </Label>,
                          ]
                        : undefined
                    }
                  />
                }
                secondaryActions={
                  <ListItemActionBar
                    label="enterprise teams options"
                    staticMenuActions={[
                      {
                        key: 'remove-access',
                        render: () => (
                          <div style={{maxWidth: '280px'}}>
                            <ActionList.Item
                              data-testid={`unassign-license-${team.id}`}
                              onSelect={() => handleOpenLicenseRemovalDialog(team.id)}
                            >
                              <span className={'color-fg-danger'}>Remove access</span>
                              <p className={'color-fg-muted mt-1'}>Remove this team&apos;s licenses.</p>
                            </ActionList.Item>
                          </div>
                        ),
                      },
                    ]}
                  />
                }
              >
                <ListItemMainContent>
                  <ListItemDescription>
                    <ListItemDescriptionItem>
                      {`${pluralize('member', team.memberCount, true)}`}
                    </ListItemDescriptionItem>
                  </ListItemDescription>
                </ListItemMainContent>
              </ListItem>
            ))}
          </ListView>
        )

        if (totalPages > 1) {
          pagination = (
            <div className="mt-3 d-flex flex-justify-center">
              <Pagination
                currentPage={currentPage}
                pageCount={totalPages}
                onPageChange={(_, newPage) => navigateToPage(newPage)}
              />
            </div>
          )
        }
      }
    }
  }

  return (
    <>
      {props.isCopilotBusinessTeamFlagEnabled && (
        <div className={showBorder ? styles.emptyContainer : ''}>
          {mainContent}
          {pagination}
          {selectedTeamForDialog !== null && (
            <CopilotBusinessTeamChangeAccessDialog
              teams={Array.isArray(selectedTeamForDialog) ? selectedTeamForDialog : [selectedTeamForDialog]}
              downgrade
              onClose={handleCloseLicenseRemovalDialog}
              isTrial={props.isTrial}
            />
          )}
        </div>
      )}
    </>
  )
}

try{ CopilotBusinessTeamAccessList.displayName ||= 'CopilotBusinessTeamAccessList' } catch {}