import {UnderlineNav, Button, Label} from '@primer/react'
import {useCallback, useState} from 'react'
import {PeopleIcon, PersonIcon, OrganizationIcon} from '@primer/octicons-react'
import {CopilotOrganizationAccessList} from './organizations/CopilotOrganizationAccessList'
import {CopilotBusinessTeamGrantAccessDialog} from './business_teams/CopilotBusinessTeamGrantAccessDialog'
import {CopilotUserAccessList} from './users/CopilotUserAccessList'
import {CopilotAllMembersAccessList} from './users/CopilotAllMembersAccessList'
import {CopilotBusinessTeamAccessList} from './business_teams/CopilotBusinessTeamAccessList'
import {CopilotOrganizationGrantAccessDialog} from './organizations/CopilotOrganizationGrantAccessDialog'
import {CopilotUserGrantAccessDialog} from './users/CopilotUserGrantAccessDialog'
import {SearchBar} from '@github-ui/licensing-common/components/SearchBar'
import styles from './CopilotAccessList.module.css'
import {useSearchParams} from '@github-ui/react-router'

export interface CopilotAccessListProps {
  accessibleOrganizationCount: number
  enabledUserCount: number
  enabledBusinessTeamCount: number
  enabledAllMembersCount: number
  isCopilotUserFlagEnabled: boolean
  isCopilotBusinessTeamFlagEnabled: boolean
  isCopilotAllMembersFlagEnabled: boolean
  atMaxCopilotLicenseCount?: boolean
  isTrial: boolean
}

export function CopilotAccessList(props: CopilotAccessListProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [searchParams, setSearchParams] = useSearchParams()
  const initialTab =
    searchParams.get('tab') ||
    (props.isCopilotUserFlagEnabled
      ? props.isCopilotAllMembersFlagEnabled
        ? 'all_members'
        : 'users'
      : 'organizations')
  const [selectedTab, setSelectedTab] = useState(initialTab)

  const handleTabChange = (tab: string) => {
    setSelectedTab(tab)
    searchParams.delete('page')
    searchParams.set('tab', tab)
    setSearchParams(searchParams)
  }

  const [openGrantAccessDialog, setOpenGrantAccessDialog] = useState(false)

  const onDialogClose = useCallback(() => setOpenGrantAccessDialog(false), [])

  return (
    <div className="mb-3 pb-3" data-testid="licensing-copilot-access-list">
      <div className="pb-3">
        <UnderlineNav aria-label="Copilot access tabs" className={styles.underlineNav}>
          {props.isCopilotUserFlagEnabled && !props.isCopilotAllMembersFlagEnabled && (
            <UnderlineNav.Item
              aria-current={selectedTab === 'users' ? 'page' : undefined}
              onClick={() => handleTabChange('users')}
              counter={props.enabledUserCount}
              icon={<PersonIcon size={16} />}
              data-testid="licensing-copilot-users-access-tab"
            >
              <span>Users</span>
            </UnderlineNav.Item>
          )}
          {props.isCopilotAllMembersFlagEnabled && (
            <UnderlineNav.Item
              aria-current={selectedTab === 'all_members' ? 'page' : undefined}
              onClick={() => handleTabChange('all_members')}
              counter={props.enabledAllMembersCount}
              icon={<PersonIcon size={16} />}
              data-testid="licensing-copilot-all-members-access-tab"
            >
              <span>All members</span>
            </UnderlineNav.Item>
          )}
          {props.isCopilotBusinessTeamFlagEnabled && (
            <UnderlineNav.Item
              aria-current={selectedTab === 'enterprise_teams' ? 'page' : undefined}
              onClick={() => handleTabChange('enterprise_teams')}
              counter={props.enabledBusinessTeamCount}
              icon={<PeopleIcon size={16} />}
              data-testid="licensing-copilot-enterprise-teams-access-tab"
            >
              <span>Enterprise Teams</span>
            </UnderlineNav.Item>
          )}
          <UnderlineNav.Item
            aria-current={selectedTab === 'organizations' ? 'page' : undefined}
            onClick={() => handleTabChange('organizations')}
            counter={props.accessibleOrganizationCount}
            icon={<OrganizationIcon size={16} />}
            data-testid="licensing-copilot-organization-access-tab"
          >
            Organizations
          </UnderlineNav.Item>
        </UnderlineNav>
      </div>

      {/** Make this text variable based on the tab */}
      <p className={styles.tabDescription}>
        {(() => {
          switch (selectedTab) {
            case 'organizations':
              return 'Users assigned licenses across multiple organizations will only be billed once.'
            case 'enterprise_teams':
              return (
                <span>
                  <Label variant="success">Preview</Label> Directly assign enterprise teams Copilot Business licenses.
                  If members have access to both a Copilot Business license and a Copilot Enterprise license, they will
                  only be charged for the Enterprise license.
                </span>
              )
            case 'all_members':
              if (props.isCopilotAllMembersFlagEnabled) {
                return 'List of all enterprise members with a Copilot license across organizations, enterprise teams and directly assigned here.'
              }
              break
            case 'users':
            default:
              return 'Directly assign Copilot Business licenses to users. If they have access to both a Copilot Business license and a Copilot Enterprise license they will only be charged for the Copilot Enterprise license.'
          }
        })()}
      </p>

      <div className="d-flex flex-row">
        <div className="flex-1">
          <SearchBar
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            placeholder={
              selectedTab === 'organizations'
                ? 'Search or filter organizations'
                : selectedTab === 'enterprise_teams'
                  ? 'Search or filter enterprise teams'
                  : 'Search or filter members'
            }
            ariaLabel={
              selectedTab === 'organizations'
                ? 'Search or filter organizations'
                : selectedTab === 'enterprise_teams'
                  ? 'Search or filter enterprise teams'
                  : 'Search or filter members'
            }
          />
        </div>

        {!(selectedTab === 'organizations' && props.isTrial) && (
          <div className="ml-2">
            <Button variant="primary" onClick={() => setOpenGrantAccessDialog(true)}>
              {selectedTab === 'organizations' ? 'Grant access' : 'Assign licenses'}
            </Button>
          </div>
        )}

        {openGrantAccessDialog === true && selectedTab === 'organizations' && !props.isTrial && (
          <CopilotOrganizationGrantAccessDialog onDialogClose={onDialogClose} />
        )}
        {openGrantAccessDialog === true &&
          props.isCopilotBusinessTeamFlagEnabled &&
          selectedTab === 'enterprise_teams' && (
            <CopilotBusinessTeamGrantAccessDialog
              onDialogClose={onDialogClose}
              atMaxCopilotLicenseCount={props.atMaxCopilotLicenseCount}
            />
          )}
        {openGrantAccessDialog === true && props.isCopilotUserFlagEnabled && selectedTab === 'users' && (
          <CopilotUserGrantAccessDialog
            onDialogClose={onDialogClose}
            atMaxCopilotLicenseCount={props.atMaxCopilotLicenseCount}
          />
        )}
        {openGrantAccessDialog === true && props.isCopilotAllMembersFlagEnabled && selectedTab === 'all_members' && (
          <CopilotUserGrantAccessDialog
            onDialogClose={onDialogClose}
            atMaxCopilotLicenseCount={props.atMaxCopilotLicenseCount}
            isCopilotAllMembersFlagEnabled={props.isCopilotAllMembersFlagEnabled}
          />
        )}
      </div>
      {selectedTab === 'organizations' && (
        <CopilotOrganizationAccessList
          setOpenGrantAccessDialog={setOpenGrantAccessDialog}
          searchQuery={searchQuery}
          isTrial={props.isTrial}
        />
      )}
      {selectedTab === 'enterprise_teams' && (
        <CopilotBusinessTeamAccessList
          setOpenGrantAccessDialog={setOpenGrantAccessDialog}
          searchQuery={searchQuery}
          isCopilotBusinessTeamFlagEnabled={props.isCopilotBusinessTeamFlagEnabled}
          isTrial={props.isTrial}
        />
      )}
      {selectedTab === 'users' && (
        <CopilotUserAccessList
          setOpenGrantAccessDialog={setOpenGrantAccessDialog}
          searchQuery={searchQuery}
          isCopilotUserFlagEnabled={props.isCopilotUserFlagEnabled}
          isTrial={props.isTrial}
        />
      )}
      {selectedTab === 'all_members' && (
        <CopilotAllMembersAccessList
          searchQuery={searchQuery}
          isCopilotAllMembersFlagEnabled={props.isCopilotAllMembersFlagEnabled}
          isTrial={props.isTrial}
        />
      )}
    </div>
  )
}

try{ CopilotAccessList.displayName ||= 'CopilotAccessList' } catch {}