import type {ComponentPropsWithoutRef, ReactNode} from 'react'
import {NavigationContextProvider} from '../contexts/NavigationContext'
import {clsx} from 'clsx'

type NavigationProviderProps = Parameters<typeof NavigationContextProvider>[0]
type NavigationProps = Omit<NavigationProviderProps, 'children'>
type ContainerProps = Omit<ComponentPropsWithoutRef<'div'>, 'children'> & {'data-testid'?: string}

export interface SubPageLayoutProps extends NavigationProps {
  children: ReactNode
  header?: ReactNode
  containerProps?: ContainerProps
}

export function SubPageLayout({
  children,
  header,
  containerProps,
  enterpriseContactUrl,
  slug,
  isStafftools = false,
  isTeams = false,
}: SubPageLayoutProps) {
  const {className, ...restContainerProps} = containerProps ?? {}

  return (
    <NavigationContextProvider
      enterpriseContactUrl={enterpriseContactUrl}
      slug={slug}
      isStafftools={isStafftools}
      isTeams={isTeams}
    >
      <div {...restContainerProps} className={clsx('mb-4', className)}>
        {header}
        {children}
      </div>
    </NavigationContextProvider>
  )
}

try{ SubPageLayout.displayName ||= 'SubPageLayout' } catch {}